// ListRunsAll автоматически обходит все страницы курсорной пагинации метода ListRuns и возвращает полный срез элементов.
func (s *AutomationsService) ListRunsAll(ctx context.Context, params *AutomationsListRunsParams) ([]AutomationRun, error) {
	var p AutomationsListRunsParams
	if params != nil {
		p = *params
	}
	var all []AutomationRun
	for {
		page, err := s.ListRuns(ctx, &p)
		if err != nil {
			return nil, err
		}
		if page != nil {
			all = append(all, page.Data...)
		}
		if page == nil || page.NextCursor == nil || *page.NextCursor == "" {
			break
		}
		next := *page.NextCursor
		p.Cursor = &next
	}
	return all, nil
}

